#!/usr/bin/env python3
"""sen0414_lineage_exam_rev v1_0_0 - records (ONE new register file) the Owner's corrections of 2026-11-02 12:09 Istanbul (relayed) as the story ST4_Rev with seven build tasks and seven controls, all Ready, ranked, with the objective Obj5_Corrections (0 to 6) and its first reading; open scores re-run. Briefs: 08-tooling/briefs/exam/r15.
Usage: sen0414_lineage_exam_rev_v1_0_0.py"""
__version__ = "1.0.0"
import os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sen0414_lineage_standard_v1_2_0 as W
def blk(t, name):
    i = t.index("\nex:%s a backlog:" % name) + 1; j = t.find("\nex:", i + 1)
    return i, (len(t) if j < 0 else j)
BR = "08-tooling/briefs/exam/r15/BRIEF_%s.md"
OWN = ("OWNER CORRECTIONS of 2026-11-02 (his words of 12:09 Istanbul on the SEN0401 exam, relayed by the course coordinator and recorded as relayed, with the order to apply the SEN0414 equivalents): (1) space on the answer sheet for every answer that has no place today; (2) the answer sheet is only an option, the legal copy is the answers on the question sheets, every sub-question has an answer space on the question pages and the directions say the question pages count if the two differ; (3) anything out of scope is removed; (4) directions and every answer-format line in plain words, the same words beside the answer space; (5) tips out of the stems, on a tips page as the second page of the answer sheet, with a stem-length rule with fixtures; (6) a wrong choice costs 1/3 of the item's points (blank 0) so a blind answer gains nothing, other answer types by the same principle, the rule printed in one plain sentence, the reader and the key apply it. Target: the single midterm form (the Owner dropped forms A and B). All new exam artefacts go to the private CME repository, never to the public one. Stipulations the lineage agent could not derive and reports for the Owner to confirm: the stem length (10 to 20 words), the tip length (25 words), the floor of the score (paper total not below 0, no floor inside a question), the page budget (cover 1, at most 4 question pages, sheet 2).")
TASKS = [  # id, title, type, hours, session, depends on (verify ids of predecessors), text
 ("TK4_Rev_Design", "Design v1.3.0: scoring, stem and tip rules, answer spaces, plain sentences, one form", 1.0, ["TK4_Cover_Verify"]),
 ("TK4_Rev_Valid", "Item validator v1.2.0: stem, tip, scope and plain-sentence rules with a taught vocabulary", 1.5, ["TK4_Rev_Design_Verify"]),
 ("TK4_Rev_Sheet", "Answer sheet v2.0.0: two pages, a place for every unit, tips page, rule 5 inside the margin, reader", 2.5, ["TK4_Rev_Design_Verify"]),
 ("TK4_Rev_Items", "Single midterm item list v3.0.0: short stems, tips apart, in scope, plain sentences", 3.0, ["TK4_Rev_Design_Verify", "TK4_Rev_Valid_Verify"]),
 ("TK4_Rev_Engine", "Engine v1.2.0: stem, answer space, tips page, scoring table, directions, one form", 2.0, ["TK4_Rev_Design_Verify", "TK4_Rev_Valid_Verify"]),
 ("TK4_Rev_Papers", "Renderer v1.1.0 and the single midterm form with answer spaces, directions, tips page", 2.5, ["TK4_Rev_Sheet_Verify", "TK4_Rev_Items_Verify", "TK4_Rev_Engine_Verify"]),
 ("TK4_Rev_Score", "Marking tool with the penalty rule and the measured blind-answer proof", 1.5, ["TK4_Rev_Sheet_Verify", "TK4_Rev_Engine_Verify"])]
def main():
    src = W.newest(); t = open(src, encoding="utf-8").read(); now = W.now(); nowZ = now + "Z"; add = []
    sid = "ST4_Rev"; ids = [x[0] for x in TASKS]; allt = ids + [i + "_Verify" for i in ids]
    size = sum(x[2] for x in TASKS) + 0.5 * len(TASKS); bv, tc, rr = 20, 20, 10; val = (bv + tc + rr) / size
    add.append('\nex:%s a backlog:Story ; rdfs:label "The Owner\'s corrections of the midterm: answer spaces, plain directions, tips page, penalty"@en ; backlog:hasIdentifier "%s" ; backlog:hasTitle "The Owner\'s corrections of the midterm: answer spaces, plain directions, tips page, penalty" ;\n    backlog:belongsToLineage ex:Lineage4 ; backlog:memberOfContainer ex:Iter_Ex3 ; backlog:responsible ex:Executor_ClaudeCodeSession ; backlog:admittedByOutput ex:Out4_Backlog ;\n    backlog:hasInvestmentCategory backlog:Cat_NewCapability ;\n    backlog:asRole "SEN0414 instructor" ; backlog:wantsCapability "the single midterm form with an answer space for every sub-question, plain directions, a tips page, short in-scope stems and a scoring rule that gives a blind answer nothing" ; backlog:soThat "the printed question pages are the legal answers, a student reads every direction without help, and guessing does not pay" ;\n    backlog:satisfiesDeliverable ex:Del4_Papers ; backlog:pursuesObjective ex:Obj5_Corrections ; backlog:hasAcceptanceCriterion ex:AC4_Controlled ;\n    backlog:coversEntity ex:DE4_ExamPaper, ex:DE4_AnswerKey ; backlog:coversStage backlog:Stage_Creation ;\n    backlog:effectiveDefinitionOfDone ex:DoD ; backlog:hasApplicableConcern backlog:Concern_Data ;\n    backlog:decomposesInto %s ;\n    backlog:hasState backlog:Ready ; backlog:hasPriorityScore ex:Score5c_%s ;\n    backlog:hasAuditNote %s .\n' % (sid, sid, ", ".join("ex:" + k for k in allt), sid, W.lit(OWN + " Briefs: 08-tooling/briefs/exam/r15 (seven, one per build task). This story absorbs the deliverable of ST4_Rule5 (rule 5 inside the margin): TK4_Rev_Sheet builds it in the new sheet copy and its control checks it; ST4_Rule5 closes on that evidence.")))
    add.append('ex:Score5c_%s a backlog:PriorityScore ; backlog:scoredByMethod backlog:Method_WSJF ;\n    backlog:hasScoreValue "%.2f"^^xsd:decimal ; backlog:scoredAt "%s"^^xsd:dateTime ; backlog:isAveragedFromMembers false ;\n    backlog:hasScoreRationale %s .\n' % (sid, val, nowZ, W.lit("WSJF = (business value %d + time criticality %d + risk reduction %d) / job size %.1f h = %.2f. First scoring %s UTC: the Owner ordered the corrections for the midterm; the sitting depends on them; job size is the sum of the estimates of the seven builds and seven controls." % (bv, tc, rr, size, val, now))))
    add.append('ex:Met5_Corrections a backlog:Metric ; rdfs:label "Owner corrections applied and controlled on the single midterm form"@en ; backlog:belongsToLineage ex:Lineage4 .\nex:Obj5_Corrections a backlog:Objective ; rdfs:label "The six corrections of the Owner on the single midterm form: from 0 to 6"@en ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:contributesToGoal ex:G4_PapersExist ; backlog:fillsScope ex:Scope4 ; backlog:hasSuccessMetric ex:Met5_Corrections ;\n    backlog:hasMeasurementKind backlog:Meas_Counted ;\n    backlog:hasMeasurementQuery "Counted by the controller: one for each of the six corrections (answer places, legal copy and directions, scope, plain sentences, tips page and stem rule, penalty) that its own checks on the built single form confirm." ;\n    backlog:hasBaselineValue "0"^^xsd:decimal ; backlog:hasTargetValue "6"^^xsd:decimal ; backlog:hasTargetDirection backlog:Dir_Increase ;\n    backlog:hasCheckpoint ex:CP5_Obj5_Corrections ;\n    backlog:hasIntentOrigin backlog:IOrigin_Derived ; backlog:decidedBy backlog:Owner ; backlog:producedByStage ex:Out4_Objective .\nex:CP5_Obj5_Corrections a backlog:ObjectiveCheckpoint ; rdfs:label "Reading after the controller has checked the built form"@en ;\n    backlog:checkpointCondition "Taken after the controller\'s own re-runs of the checks on the built single form." ; backlog:expectedValue "6"^^xsd:decimal .\nex:Obj5_Corrections backlog:metricMovableBy ex:%s .\nex:Obs50_Obj5_Corrections a backlog:MetricObservation ; rdfs:label "Reading when the corrections were registered"@en ;\n    backlog:observesMetric ex:Met5_Corrections ; backlog:observationFor ex:Obj5_Corrections ; backlog:hasObservedValue "0"^^xsd:decimal ; backlog:observedAt "%s"^^xsd:dateTime ;\n    backlog:hasObservationMethod "None of the six corrections is built or controlled yet (the papers of 2026-11-02 had no answer spaces on the question pages, a one-page sheet, tips in the stems and no penalty): 0." .\n' % (sid, nowZ))
    texts = {}
    for tid, title, hours, deps in TASKS:
        for isv in (False, True):
            k = tid + ("_Verify" if isv else "")
            if isv: text_ = "Control by the lineage agent on its own re-runs of the checks named in the brief %s, the claims recomputed on the files in the private CME repository, no existing file changed, everything committed to CME; an incomplete run is a result, not a pass. Estimated 0.5 hours (an estimate, G120)." % (BR % tid)
            else: text_ = "Deliverable and checks: see the brief %s (generated by the lineage agent, r15); executor session %s; new versioned files in /home/claude/CME/exams/SEN0414, nothing in the public repository. Estimated %.1f hours (an estimate, G120). %s" % (BR % tid, "SEN0414-EX-" + tid.lower().replace("tk4_", "").replace("_", "-"), hours, OWN)
            dep = "    backlog:dependsOn %s ;\n" % ", ".join("ex:" + d for d in ([tid] if isv else deps))
            add.append('\nex:%s a backlog:ExecutionTask ; rdfs:label %s@en ; backlog:hasIdentifier "%s" ; backlog:hasTitle %s ;\n    backlog:belongsToLineage ex:Lineage4 ; backlog:memberOfContainer ex:Iter_Ex3 ; backlog:admittedByOutput ex:Out4_Backlog ; backlog:responsible ex:Executor_ClaudeCodeSession ;\n    backlog:hasInvestmentCategory backlog:%s ; backlog:hasTaskType backlog:TaskType_%s ; backlog:effectiveDefinitionOfDone ex:DoD ; backlog:hasState backlog:Ready ;\n%s    backlog:notYetScoreable true ; backlog:hasScoreabilityReason "Ranked by its story\'s state; scoring both would double-count." ;\n    backlog:hasAuditNote %s .\n' % (k, W.lit(("Verify: " if isv else "") + title), k, W.lit(("Verify: " if isv else "") + title), "Cat_Compliance" if isv else "Cat_NewCapability", "Verify" if isv else "Build", dep, W.lit(text_)))
    for k in [sid] + allt:
        add.append('ex:Refine5c_%s a backlog:RefinementEvent ; rdfs:label "Refinement that made %s ready"@en ;\n    backlog:refines ex:%s ; backlog:addressesConcern backlog:Concern_Data ; backlog:refinedAt "%s"^^xsd:dateTime ;\n    backlog:refinedBy backlog:Builder ; backlog:groomsForIteration ex:Iter_Ex3 ; backlog:hasWorkKind backlog:WorkKind_Preparation ;\n    backlog:hasRefinementOutcome "Refined from the Owner\'s corrections of 2026-11-02 (relayed): brief r15, check, estimate and dependencies are written in the item." .\n' % (k, k, k, now))
        add.append('ex:RC5c_%s a backlog:ReadinessCheck ; rdfs:label "Readiness check of %s"@en ; backlog:checksReadinessOf ex:%s ; backlog:readinessCheckedAt "%s"^^xsd:dateTime ;\n    backlog:hasReadinessCriterion ex:RK5c_%s_1, ex:RK5c_%s_2, ex:RK5c_%s_3 .\n' % (k, k, k, now, k, k, k))
        for kx, tx in ((1, "The deliverable, its place and its check are written in the item or its brief."), (2, "Every dependency of the item is Done or a task of the same story that precedes it."), (3, "The statements that bound the item are recorded on the story.")):
            add.append('ex:RK5c_%s_%d a backlog:ReadinessCriterion ; rdfs:label %s@en ; backlog:criterionMet true .\n' % (k, kx, W.lit(tx)))
        add.append('ex:Mv5c_%s a backlog:TransitionEvent ; rdfs:label %s@en ; backlog:transitionedItem ex:%s ;\n    backlog:viaTransition backlog:T_Refine ; backlog:transitionedAt "%s"^^xsd:dateTime ; backlog:transitionedBy backlog:Builder ;\n    backlog:hasTransitionNote %s .\n' % (k, W.lit(k + " moved to Ready"), k, nowZ, W.lit("Refined (ex:Refine5c_%s) and ready after the readiness check ex:RC5c_%s; no executor has started." % (k, k))))
    add.append('ex:Plan5c_%s a backlog:PlanningEvent ; rdfs:label "Planning of %s into box 3"@en ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:plannedAt "%s"^^xsd:dateTime ; backlog:plannedBy backlog:Builder ; backlog:plannedInto ex:Iter_Ex3 ;\n    backlog:plansItem ex:%s ; backlog:producesTask %s ;\n    backlog:refinementProduces ex:Spec4, ex:Scen4_Sound, ex:Scen4_Refused .\n' % (sid, sid, now, sid, ", ".join("ex:" + k for k in allt)))
    add.append("ex:Iter_Ex3 backlog:hasMember ex:%s, %s .\nex:EP4_Engine backlog:decomposesInto ex:%s .\n" % (sid, ", ".join("ex:" + k for k in allt), sid))
    NS = "http://example.org/sen0414-slides-lineage#"
    add.append("".join("<%sUrgent_4> backlog:urgentItem <%s%s> .\n" % (NS, NS, k) for k in [sid] + allt))
    done_loop = []
    for s2 in sorted(set(re.findall(r"\nex:(ST\w*?_\w+) a backlog:Story", t))):
        i, j = blk(t, s2); b = t[i:j]
        m = re.search(r"backlog:hasPriorityScore ex:Score(\d+[a-z]?)_%s\b" % s2, b)
        if not m or "backlog:hasState backlog:Done" in b or "backlog:hasState backlog:Cancelled" in b: continue
        kk = m.group(1)
        if ("\nex:Score%s_%s a" % (kk, s2)) not in t: continue
        k0 = t.index("\nex:Score%s_%s a" % (kk, s2)) + 1; r0 = t[k0:t.find("\nex:", k0 + 1)]
        q = re.search(r"business value (\d+) \+ time criticality (\d+) \+ risk reduction (\d+)\) / job size ([\d.]+) h", r0)
        if not q: continue
        nk = (kk[:-1] + chr(ord(kk[-1]) + 1)) if kk[-1].isalpha() else str(int(kk) + 1); nid = "Score%s_%s" % (nk, s2)
        if ("ex:" + nid + " a ") in t: continue
        bv_, tc_, rr_, sz_ = int(q.group(1)), int(q.group(2)), int(q.group(3)), float(q.group(4)); v_ = (bv_ + tc_ + rr_) / sz_
        t = t[:i] + b.replace(m.group(0), "backlog:hasPriorityScore ex:" + nid, 1) + t[j:]
        add.append('ex:%s a backlog:PriorityScore ; backlog:scoredByMethod backlog:Method_WSJF ;\n    backlog:hasScoreValue "%.2f"^^xsd:decimal ; backlog:scoredAt "%s"^^xsd:dateTime ; backlog:isAveragedFromMembers false ;\n    backlog:hasScoreRationale %s .\n' % (nid, v_, nowZ, W.lit("WSJF = (business value %d + time criticality %d + risk reduction %d) / job size %.1f h = %.2f. RE-RUN on %s UTC after the story ST4_Rev (the Owner\'s corrections) entered the backlog. Inputs unchanged." % (bv_, tc_, rr_, sz_, v_, now))))
        done_loop.append(s2)
    add.append("ex:Lineage4 backlog:hasAuditNote %s .\n" % W.lit("RANKING %s UTC after the Owner's corrections of the midterm entered as ST4_Rev (relayed): 1 the Ready chain TK4_Rev_Design, then TK4_Rev_Valid and TK4_Rev_Sheet and TK4_Rev_Engine in parallel, TK4_Rev_Items, TK4_Rev_Score, TK4_Rev_Papers; ST4_Rule5 is absorbed by TK4_Rev_Sheet; the make-up (ST4_MakeUp) stays last. Open scores re-run: %s." % (now, ", ".join(done_loop) or "none")))
    out = W.write_new(src, t + "\n" + "".join(add), "Exam change: the Owner's corrections of 2026-11-02 12:09 (answer spaces, plain directions, tips page, penalty) as story ST4_Rev with seven builds and seven controls Ready and ranked; objective Obj5_Corrections 0 to 6; scores re-run.")
    print(os.path.basename(out))
main()
